choose.when:
select * from application
(lower(coalesce(id, '')) like #{like} or lower(coalesce(name, '')) like #{like} or lower(coalesce(project_id, '')) like #{like})
order by created_at desc, id limit #{limit} offset #{offset}

select id, name, type, updated_at from 
(lower(coalesce(id, '')) like #{like} or lower(coalesce(name, '')) like #{like} or lower(coalesce(type, '')) like #{like})
order by case type when 'dev' then 1 when 'sit' then 2 when 'uat' then 3 when 'prod' then 4 else 99 end, id limit #{limit} offset #{offset}

select id, name, project_id, environment_id, environment_key, updated_at from 
(lower(coalesce(id, '')) like #{like} or lower(coalesce(name, '')) like #{like} or lower(coalesce(project_id, '')) like #{like} or lower(coalesce(environment_key, '')) like #{like})
order by updated_at desc, id, environment_id limit #{limit} offset #{offset}

select * from environment
(lower(coalesce(id, '')) like #{like} or lower(coalesce(name, '')) like #{like} or lower(coalesce(type, '')) like #{like} or lower(coalesce(application_id, '')) like #{like})
order by created_at desc, id limit #{limit} offset #{offset}

select  from 
(lower(coalesce(id, '')) like #{like} or lower(coalesce(nickname, '')) like #{like} or lower(coalesce(hostname, '')) like #{like} or lower(coalesce((select a.name from application a where a.id = instance.application_id), '')) like #{like} or lower(coalesce((select lower(coalesce(e.type, e.name)) from environment e where e.id = instance.environment_id), '')) like #{like} or lower(coalesce(application_id, '')) like #{like} or lower(coalesce(environment_id, '')) like #{like} or lower(coalesce(status, '')) like #{like})
order by updated_at desc, id limit #{limit} offset #{offset}

select * from sidecar_instance
(lower(coalesce(id, '')) like #{like} or lower(coalesce(endpoint, '')) like #{like} or lower(coalesce(status, '')) like #{like} or lower(coalesce(sidecar_version, '')) like #{like})
order by updated_at desc, id limit #{limit} offset #{offset}

select * from attach_executor
(lower(coalesce(id, '')) like #{like} or lower(coalesce(executor_type, '')) like #{like} or lower(coalesce(hostname, '')) like #{like} or lower(coalesce(endpoint, '')) like #{like} or lower(coalesce(status, '')) like #{like} or lower(coalesce(executor_version, '')) like #{like})
