select executor_id, instance_id, process_id, agent_jar, runtime, java_version, status, last_seen_at, created_at, updated_at from attach_executor_target
(lower(coalesce(executor_id, '')) like #{like} or lower(coalesce(instance_id, '')) like #{like} or lower(coalesce(process_id, '')) like #{like} or lower(coalesce(status, '')) like #{like})
order by updated_at desc, executor_id, instance_id limit #{limit} offset #{offset}

select id, executor_id, instance_id, command_type, status, process_id, agent_jar, attempt, max_attempts, lease_owner, lease_expires_at, error_message, created_at, updated_at, started_at, finished_at from attach_executor_command
(lower(coalesce(id, '')) like #{like} or lower(coalesce(executor_id, '')) like #{like} or lower(coalesce(instance_id, '')) like #{like} or lower(coalesce(command_type, '')) like #{like} or lower(coalesce(status, '')) like #{like})
order by updated_at desc, id limit #{limit} offset #{offset}

select id, instance_id, sidecar_id, status, agent_version, bootstrap_version, listen_host, listen_port, capabilities_json, last_heartbeat_at, created_at, updated_at from agent_instance
(lower(coalesce(id, '')) like #{like} or lower(coalesce(listen_host, '')) like #{like} or lower(coalesce(status, '')) like #{like} or lower(coalesce(agent_version, '')) like #{like})
order by updated_at desc, id limit #{limit} offset #{offset}

select * from agent_command
(lower(coalesce(id, '')) like #{like} or lower(coalesce(agent_id, '')) like #{like} or lower(coalesce(command_type, '')) like #{like} or lower(coalesce(status, '')) like #{like})
