order by created_at desc, id limit #{limit} offset #{offset}

select * from operation_plan
(lower(coalesce(id, '')) like #{like} or lower(coalesce(resource_type, '')) like #{like} or lower(coalesce(resource_id, '')) like #{like} or lower(coalesce(status, '')) like #{like})
order by updated_at desc, id limit #{limit} offset #{offset}

select id, operation_plan_id, instance_id, status, expected_agent_version, expected_rule_version, command_id, error_message, started_at, finished_at, updated_at, instance_nickname, application_name, environment_name, java_version, agent_version, load_mode, process_start_id, instance_last_seen_at, attach_executor_id from rollout_instance_execution
