select id, operation_plan_id, instance_id, labels_json, agent_status, captured_at, instance_nickname, application_name, environment_name, java_version, agent_version, load_mode, process_start_id, instance_last_seen_at, attach_executor_id from rollout_target_snapshot
(lower(coalesce(id, '')) like #{like} or lower(coalesce(operation_plan_id, '')) like #{like} or lower(coalesce(instance_id, '')) like #{like} or lower(coalesce(instance_nickname, '')) like #{like} or lower(coalesce(application_name, '')) like #{like} or lower(coalesce(environment_name, '')) like #{like} or lower(coalesce(agent_status, '')) like #{like})
order by captured_at desc, id limit #{limit} offset #{offset}

select * from rollback_execution
(lower(coalesce(id, '')) like #{like} or lower(coalesce(operation_plan_id, '')) like #{like} or lower(coalesce(rollback_type, '')) like #{like} or lower(coalesce(status, '')) like #{like} or lower(coalesce(reason, '')) like #{like})
