select id, subject_type, subject_id, status, created_by, created_at, expires_at, last_used_at, revoked_at from 
(lower(coalesce(id, '')) like #{like} or lower(coalesce(subject_id, '')) like #{like} or lower(coalesce(status, '')) like #{like})
order by created_at desc, id limit #{limit} offset #{offset}

select id, username, display_name, status, created_at from user_account
status = 'ACTIVE' and (lower(coalesce(id, '')) like #{like} or lower(coalesce(username, '')) like #{like} or lower(coalesce(display_name, '')) like #{like})
order by username, id limit #{limit} offset #{offset}

mapper.select:
select rt.class_name, rt.method_name, rt.protocol, count(*) as version_count from rule_target rt join rule_version rv on rv.id = rt.rule_version_id join rule r on r.id = rv.rule_id where rv.status = 'ENABLED' and (lower(rt.class_name) like #{like} or lower(rt.method_name) like #{like})
and r.application_id = #{applicationId}
and r.environment_id = #{environmentId}
group by rt.class_name, rt.method_name, rt.protocol order by rt.class_name, rt.method_name limit 100
